// 컴파일된 Vue 컴포넌트 라이브러리 흉내(R189 재현): render 함수 컴포넌트, __file이 node_modules 경로 — 어댑터가 라이브러리로 본다
import { defineComponent, h, Transition } from 'vue';

export const FButton = defineComponent({
  name: 'FButton',
  __file: 'lib/node_modules/fake-vue-ui/FButton.vue',
  render() { return h('button', { class: 'f-btn' }, this.$slots.default?.()); },
});

export const FCard = defineComponent({
  name: 'FCard',
  __file: 'lib/node_modules/fake-vue-ui/FCard.vue',
  render() { return h('div', { class: 'f-card' }, this.$slots.default?.()); },
});

// 내부에 <Transition>(Vue 내장: BaseTransition·Transition, __file 없음)을 둔다
export const FTag = defineComponent({
  name: 'FTag',
  __file: 'lib/node_modules/fake-vue-ui/FTag.vue',
  render() { return h(Transition, null, { default: () => h('span', { class: 'f-tag' }, this.$slots.default?.()) }); },
});
